// TH15 v1.00b st01bs.ecl BossCard2, spell 6.
// Source rows 596-694; helpers BossCard2_at (696-737) and BossCard2_at2 (739-816).
// Entry state: boss at (0,128), no residual bullets/async; local frame 0 = card frame 120.

const TIME_LIMIT: int = 2524;
const OPENING_BUFFER: int = 120;

const TH15_BULLET: int = 560;   // source etSprite type 13 (radius 2.4, colors 0-15)
const AT_COLOR: int = 4;        // BossCard2_at: etSprite(13, 4)
const AT2_COLOR: int = 6;       // BossCard2_at2: etSprite(13, 6)

const FAN_STEP: int = 364;      // 0.034906585 rad = 2 deg
const ROT_STEP: int = 40500;    // 3.883222 rad = 222.5 deg (at2 Lunatic base rotation)

// moveRand(30, 4, 1.0) under moveLimit(0, 128, 240, 64); duration 30, speed 1.0.
// int slot 0 = step count, fx slots 0/1 = unit direction (cos/sin).
sub card_arm_next_step() {
    var k: int = self_int(0) + 1;
    set_self_int(0, k);
    var speed: fx = 0fx;
    if k < 30 { speed = (30 - k) as fx / 30; }
    var nx: fx = $self_x + self_fx(0) * speed;
    var ny: fx = $self_y + self_fx(1) * speed;
    if nx < -120fx { nx = -120fx; }
    if nx > 120fx { nx = 120fx; }
    if ny < 96fx { ny = 96fx; }
    if ny > 160fx { ny = 160fx; }
    move_vel_xy(0, nx - $self_x, ny - $self_y, EASE_LINEAR);
}
sub card_begin_angle(a: angle) {
    set_self_fx(0, cos(a));
    set_self_fx(1, sin(a));
    set_self_int(0, 0);
    card_arm_next_step();
}
sub card_move_rand() {
    var r: int = rand(65536) - 32768;
    var a: int = r / 3;
    if $self_x < -60fx {
        a = r / 3;
    } else if $self_x > 60fx {
        a = r / 3 + 32768;
        if a > 32768 { a = a - 65536; }
    } else {
        a = r / 4;
        var choose: int = rand(65536) % 3;
        if $player_x > $self_x {
            if choose == 0 { a = a + 32768; }
        } else {
            if choose != 0 { a = a + 32768; }
        }
    }
    if $self_y < 112fx {
        if a < 0 { a = -a; }
    } else if $self_y > 144fx {
        if a < 0 { a = -a; }
        a = -a;
    }
    if a > -16906 && a < -15862 {
        if a < -16384 { a = -16906; } else { a = -15862; }
    } else if a > 15862 && a < 16906 {
        if a < 16384 { a = 15862; } else { a = 16906; }
    }
    card_begin_angle(a as angle);
}
sub card_wait(frames: int) {
    for i in 0..frames {
        wait(1);
        card_arm_next_step();
    }
}

// BossCard2_at: mode1 fixed fan, count 1..D ascending, step 2deg, one speed layer.
// Speed E1.5 / N2.0 / H3.5 / L3.5; gap E6 / N,H,L 4; D E6 / N,H,L 8.
// ANIM a=1 backoff: spawn 4*speed behind along each bullet's own angle.
async sub at_fan(base: angle) {
    var waves: int = 8;
    var gap: int = 4;
    var spd: fx = 2fx;
    if global(GVAR_RANK) == RANK_EASY { waves = 6; gap = 6; spd = 1.5fx; }
    if global(GVAR_RANK) >= RANK_HARD { spd = 3.5fx; }
    sh_reset(0);
    sh_sprite(0, TH15_BULLET, AT_COLOR);
    sh_ring(0, 0);
    sh_aim(0, 0);
    sh_angle(0, base, (FAN_STEP as angle));
    sh_speed(0, spd, 0fx);
    sh_dist(0, 0fx - 4fx * spd);
    for c in 1..waves+1 {
        sh_count(0, c, 1);
        sh_fire(0);
        wait(gap);
    }
}

// BossCard2_at2: mode3 fixed ring, etDist 64, ANIM a=1 backoff.
// E/N/H: 16 ways x 5 layers, v = 1.0 - 0.05q, random base per wave; delay 100 (E 300), gap 90 (E 160).
// L: 5-way ring, base starts at `base` and +222.5deg per wave, speed 1.8, delay 100, gap 4.
async sub at2_stream(base: angle) {
    var rank: int = global(GVAR_RANK);
    var delay: int = 100;
    var gap: int = 90;
    if rank == RANK_EASY { delay = 300; gap = 160; }
    if rank == RANK_LUNATIC { gap = 4; }
    wait(delay);
    var e: angle = base;
    loop {
        if rank == RANK_LUNATIC {
            sh_reset(0);
            sh_sprite(0, TH15_BULLET, AT2_COLOR);
            sh_ring(0, 1);
            sh_aim(0, 0);
            sh_count(0, 5, 1);
            sh_angle(0, e, 0deg);
            sh_speed(0, 1.8fx, 0fx);
            sh_dist(0, 64fx - 4fx * 1.8fx);
            sh_fire(0);
            e = e + (ROT_STEP as angle);
            wait(gap);
        } else {
            var r: angle = (rand(65536)) as angle;
            for q in 0..5 {
                var v: fx = 1fx - 0.05fx * (q as fx);
                sh_reset(0);
                sh_sprite(0, TH15_BULLET, AT2_COLOR);
                sh_ring(0, 1);
                sh_aim(0, 0);
                sh_count(0, 16, 1);
                sh_angle(0, r, 0deg);
                sh_speed(0, v, 0fx);
                sh_dist(0, 64fx - 4fx * v);
                sh_fire(0);
            }
            wait(gap);
        }
    }
}

async sub boss_main() {
    // Boss:8-47 entry state (hitbox 48x48 -> r24, hurtbox 40x40 -> r20 by shared rule).
    set_invuln(65535);
    set_hurtbox(20fx);
    set_hitbox(24fx);
    clear_bullets_at($self_x, $self_y, 640fx, 0);
    wait(94);
    spawn at2_stream(16384bam);     // source at2(5, +pi/2) at local t=94
    wait(40);
    spawn at2_stream(49152bam);     // source at2(6, -pi/2) at local t=134
    // Source card loop is capped at B=1000, unreachable inside the 2400-frame window.
    loop {
        var a0: angle = aim_player();
        spawn at_fan(a0);
        wait(10);
        spawn at_fan(a0 + 60deg);
        wait(10);
        spawn at_fan(a0 - 60deg);
        wait(10);
        spawn at_fan(a0 - 30deg);
        wait(10);
        spawn at_fan(a0 + 30deg);
        wait(10);
        if global(GVAR_RANK) >= RANK_HARD {
            var a1: angle = aim_player();
            spawn at_fan(a1 - 30deg);
            wait(10);
            spawn at_fan(a1 + 15deg);
            wait(10);
            spawn at_fan(a1 - 15deg);
            wait(10);
            spawn at_fan(a1 + 30deg);
            wait(10);
            spawn at_fan(a1);
        }
        wait(60);
        card_move_rand();
        card_wait(40);
    }
}

async sub pattern() {
    wait(OPENING_BUFFER);
    _ = spawn_enemy(0fx, 128fx, 1900, 0, 0, 0, boss_main);
}

async sub control() {
    set_invuln(65535);
    set_enemy_flag(ENEMY_NO_BODY, 1);
    phase_begin(0, pattern, TIME_LIMIT, 0);
    wait_spell();
    loop { wait(1); }
}

sub main() {
    _ = spawn_enemy(0fx, 0fx, 1000, 0, 0, 0, control);
    loop { wait(600); }
}
